for tool in /usr/bin/cmake /usr/bin/g++ /usr/bin/git /usr/bin/python3 /usr/local/cuda/bin/nvcc; do
  test -x "$tool" || { echo "Required probed tool missing: $tool" >&2; exit 1; }
